const body = $input.first().json.body || $input.first().json;
const callbackQuery = body.callback_query;
if (!callbackQuery) throw new Error('No callback_query en payload: ' + JSON.stringify(body));

const data = callbackQuery.data || '';
const parts = data.split('_');
const action = parts[0];
const post_id = parts.slice(1).join('_');
const callback_query_id = callbackQuery.id;
const message_id = callbackQuery.message?.message_id;
const chat_id = callbackQuery.message?.chat?.id;

if (!action || !post_id) throw new Error('callback_data inválido: ' + data);
if (action !== 'aprobar' && action !== 'rechazar') throw new Error('action desconocida: ' + action);

return [{ json: { action, post_id, callback_query_id, message_id, chat_id } }];

// Meta requiere unos segundos para procesar el container antes de poder publicarlo.
// Sin esto, /media_publish devuelve 9007 'Media ID is not available'.
await new Promise(r => setTimeout(r, 5000));
return $input.all();

const post = $('Obtener datos del post').first().json;
const errors = [];

const personal = $('LinkedIn — publicar post').first().json;
if (personal && personal.error) {
  const e = personal.error;
  errors.push('Personal: ' + (typeof e === 'string' ? e : (e.message || JSON.stringify(e))));
}

let org = null;
try {
  org = $('LinkedIn Org — publicar post').first().json;
} catch (e) {
  org = null; // rama Org no se ejecuto (LINKEDIN_ORGANIZATION_URN vacio) - no es un fallo
}
if (org && org.error) {
  const e = org.error;
  errors.push('Org: ' + (typeof e === 'string' ? e : (e.message || JSON.stringify(e))));
}

return [{
  json: {
    id: post.id,
    scheduled_date: post.scheduled_date,
    scheduled_time: post.scheduled_time,
    pillar: post.pillar,
    linkedin_ok: errors.length === 0,
    error_detail: errors.join(' | '),
  }
}];
